def isL(ns):
    h,w=len(ns),len(ns[0])
    if h<2 or w<2: return False
    def fullrow(r): return all(ns[r])
    def fullcol(c): return all(ns[r][c] for r in range(h))
    # corner sharing: full row and full col that intersect at an end
    for r in (0,h-1):
        if not fullrow(r): continue
        for c in (0,w-1):
            if fullcol(c): return True
    return False
